package com.openggf.game.soniccd.player;
import com.openggf.game.soniccd.CdReleaseVariant;
import com.openggf.game.soniccd.level.*;import com.openggf.game.soniccd.media.CdProgramAssets;
import org.junit.jupiter.api.Test;import java.nio.file.*;import java.util.*;import java.util.concurrent.atomic.AtomicReference;
import static com.openggf.game.soniccd.player.CdR4WaterAirPorts.*;
import static com.openggf.game.soniccd.player.CdPlayerFrameRuntime.OriginalWaterPortKind.*;
import static org.junit.jupiter.api.Assertions.*;import static org.junit.jupiter.api.Assumptions.assumeTrue;
/** Explicit constructed Frame controls over genuine source. No public World/Ready claim. */
class TestCdOriginalFirstWaterPortOwnership {
 private CdStagePlayerSource source()throws Exception{String root=System.getProperty("soniccd.media.root","");Path cue=Path.of(root,"USA","Sonic CD (US).cue");assumeTrue(!root.isBlank()&&Files.isRegularFile(cue));try(var a=CdProgramAssets.open(cue,Optional.of(CdReleaseVariant.USA),Optional.empty())){return CdStagePlayerSource.fromProgramme(a,CdR4DataLayout.Programme.R41A.payload().stage());}}
 static final class Fault extends RuntimeException{Fault(String m){super(m);}}
 static final class H extends TestCdOriginalProgrammeFrameSemanticCharge.H {
  String fail;boolean after,probe;H foreign;final Fault fault=new Fault("water prefix");final List<String> writes=new ArrayList<>();CdPlayerFrameRuntime.OriginalProgrammeCall issued;
  H(CdStagePlayerSource source){super(source,true);values.flags(0);values.y(0x300);values.vx(0x200);values.vy(0x400);values.water.put(Value.WATER_Y,0x280);values.water.put(Value.DROWN_TIMER,17);var a=frame.captureActor();frame.restoreActor(new CdPlayerFrameRuntime.ActorState(a.owner(),values.state,a.display()));}
  void hit(String site,Runnable write){if(site.equals(fail)&&!after)throw fault;write.run();writes.add(site);if(site.equals(fail)&&after)throw fault;}
  final Slot reserved=new Slot(){
   public int read(B f){frame.requireOriginalWaterPort(SLOT_READ,this,f,0);return values.reserved.read(f);}public int read(W f){frame.requireOriginalWaterPort(SLOT_READ,this,f,0);return values.reserved.read(f);}public int read(L f){frame.requireOriginalWaterPort(SLOT_READ,this,f,0);return values.reserved.read(f);}
   public void write(B f,int v){issued=frame.requireOriginalWaterPort(SLOT_WRITE,this,f,v);if(probe){assertThrows(IllegalStateException.class,()->frame.requireOriginalWaterPort(SLOT_WRITE,new Object(),f,v));if(foreign!=null)assertThrows(IllegalStateException.class,()->foreign.frame.requireOriginalWaterPort(SLOT_WRITE,this,f,v));var error=new AtomicReference<Throwable>();var t=new Thread(()->{try{frame.requireOriginalWaterPort(SLOT_WRITE,this,f,v);}catch(Throwable x){error.set(x);}});t.start();try{t.join();}catch(InterruptedException x){throw new AssertionError(x);}assertInstanceOf(IllegalStateException.class,error.get());}hit(f.name(),()->values.reserved.write(f,v));}
   public void write(W f,int v){frame.requireOriginalWaterPort(SLOT_WRITE,this,f,v);hit(f.name(),()->values.reserved.write(f,v));}public void write(L f,int v){frame.requireOriginalWaterPort(SLOT_WRITE,this,f,v);hit(f.name(),()->values.reserved.write(f,v));}
  };
  final Calls ports=new Calls(){
   public int read(Value f){frame.requireOriginalWaterPort(VALUE_READ,null,f,0);return values.read(f);}public void write(Value f,int v){issued=frame.requireOriginalWaterPort(VALUE_WRITE,null,f,v);hit(f.name(),()->values.write(f,v));}
   public Slot player(){throw new AssertionError("Frame owns primary");}public Slot reservedBubbles(){frame.requireOriginalWaterPort(RESERVED,null,null,0);return reserved;}
   public Optional<Slot> spawn(){frame.requireOriginalWaterPort(SPAWN,null,null,0);if("spawn".equals(fail))throw fault;return Optional.empty();}public int random(){throw new AssertionError("No RNG in PlayerCheckWater");}
   public void sound(int id){frame.requireOriginalWaterPort(SOUND,null,null,id);}public void music(int id){frame.requireOriginalWaterPort(MUSIC,null,null,id);}public CdPlayerMath.SineCosine sineCosine(int angle){throw new AssertionError("No sine");}public void setPlayerGround(){throw new AssertionError("No death");}
   public void move(Slot s){throw new AssertionError("No move");}public void animate(Slot s,Animation a){throw new AssertionError("No animation");}public void draw(Slot s){throw new AssertionError("No draw");}public void delete(Slot s){throw new AssertionError("No delete");}
  };
  @Override public Calls water(CdPlayerFrameRuntime.OriginalProgrammeCall c){c.requireCurrent(frame);return ports;}
  void run(){input(0);frame.runOriginalProgrammeBody(this);}
 }
 @Test void firstEntryWritesExistingTimerReservedAliasAndPhysicsWithoutAnotherOwner()throws Exception{var h=new H(source());h.run();assertEquals(30,h.values.water.get(Value.DROWN_TIMER).intValue());assertEquals(List.of("DROWN_TIMER","COUNTDOWN","ID","SUBTYPE"),h.writes);assertEquals(0x21,h.values.reserved.read(B.ID));assertEquals(0x81,h.values.reserved.read(B.SUBTYPE));assertEquals(0x300,h.frame.environment().movement().physics().topSpeed());assertEquals(0x100,h.frame.state().motion().xVelocity());assertEquals(0x100,h.frame.state().motion().yVelocity());}
 @Test void refusedDrownStoreRetainsWaterFlagAndHistoryWithoutPublishingTimerOrPhysics()throws Exception{var h=new H(source());h.fail="DROWN_TIMER";assertSame(h.fault,assertThrows(Fault.class,h::run));assertEquals(17,h.values.water.get(Value.DROWN_TIMER).intValue());assertTrue(h.writes.isEmpty());assertEquals(0x40,h.frame.state().motion().flags()&0x40);assertEquals(4,h.frame.state().history().index());assertEquals(0x600,h.frame.environment().movement().physics().topSpeed());}
 @Test void landedDrownFaultRetainsTheNativeWordAndOriginalException()throws Exception{var h=new H(source());h.fail="DROWN_TIMER";h.after=true;assertSame(h.fault,assertThrows(Fault.class,h::run));assertEquals(30,h.values.water.get(Value.DROWN_TIMER).intValue());assertEquals(List.of("DROWN_TIMER"),h.writes);assertEquals(0,h.values.reserved.read(B.ID));assertEquals(0x40,h.frame.state().motion().flags()&0x40);}
 @Test void reservedIdFailureKeepsEarlierCountdownAndTimerButNotSubtypeOrPhysics()throws Exception{var h=new H(source());h.fail="ID";h.after=true;assertSame(h.fault,assertThrows(Fault.class,h::run));assertEquals(List.of("DROWN_TIMER","COUNTDOWN","ID"),h.writes);assertEquals(0x21,h.values.reserved.read(B.ID));assertEquals(0,h.values.reserved.read(B.SUBTYPE));assertEquals(0x600,h.frame.environment().movement().physics().topSpeed());}
 @Test void lateSpawnFaultKeepsAllCompletedPhysicsVelocityAndReservedStores()throws Exception{var h=new H(source());h.fail="spawn";assertSame(h.fault,assertThrows(Fault.class,h::run));assertEquals(0x300,h.frame.environment().movement().physics().topSpeed());assertEquals(6,h.frame.environment().movement().physics().acceleration());assertEquals(0x40,h.frame.environment().movement().physics().deceleration());assertEquals(0x100,h.frame.state().motion().xVelocity());assertEquals(0x100,h.frame.state().motion().yVelocity());assertEquals(0x81,h.values.reserved.read(B.SUBTYPE));}
 @Test void activeReceiptRejectsWrongReceiverThreadAndRetiresOnReturn()throws Exception{var h=new H(source());h.probe=true;h.foreign=new H(source());assertNotSame(h.source,h.foreign.source);var before=h.foreign.frame.captureActor();var shared=h.foreign.frame.captureShared();h.run();assertEquals(before,h.foreign.frame.captureActor());assertEquals(shared,h.foreign.frame.captureShared());assertNotNull(h.issued);assertThrows(IllegalStateException.class,()->h.reserved.write(B.ID,0));assertThrows(IllegalStateException.class,()->h.frame.requireOriginalWaterPort(VALUE_WRITE,null,Value.DROWN_TIMER,4));assertFalse(h.frame.closed());}
 @Test void wetRepeatAndZeroVerticalEntryDoNotSpeculativelyAllocate()throws Exception{var h=new H(source());h.values.flags(0x40);var a=h.frame.captureActor();h.frame.restoreActor(new CdPlayerFrameRuntime.ActorState(a.owner(),h.values.state,a.display()));h.fail="spawn";h.run();assertTrue(h.writes.isEmpty());var zero=new H(source());zero.values.vy(0);a=zero.frame.captureActor();zero.frame.restoreActor(new CdPlayerFrameRuntime.ActorState(a.owner(),zero.values.state,a.display()));zero.fail="spawn";assertDoesNotThrow(zero::run);}
}
